use helixlane::launch::*;
fn args(v:&[&str])->Vec<String>{v.iter().map(|v|v.to_string()).collect()}
fn open(v:&[&str])->OpenRequest {match parse_native(&args(v)).unwrap(){Entry::Open(r)=>r,_=>panic!("expected request")}}
#[test] fn native_uri_and_saved_resource_parity(){let a=open(&["open","sftp://alice@example.invalid:2222/a%20b","--name","A"]);let b=open(&["helixlane://open?protocol=sftp&host=example.invalid&user=alice&port=2222&path=%2Fa%20b&name=A"]);assert_eq!(a.connection(),b.connection());assert_eq!(a.remote_path,b.remote_path);assert_eq!(a.name,b.name);assert!(parse_native(&args(&["open","--resource","1","--user","alice"])).is_err());}
#[test] fn unsafe_inputs_are_sanitized(){for value in ["helixlane://open?host=x&password=canary", "helixlane://open?host=x&host=y", "helixlane://open?host=%ZZ", "helixlane://open?host=x&path=%FF", "ssh://u:canary@host", "helixlane://open?host=x&path=%00"] {let error=parse_native(&args(&[value])).unwrap_err();assert!(!error.contains("canary"));} assert!(parse_native(&args(&["open","host;touch x"])).is_err());}
#[test] fn proxies_preserve_tokens_and_decode_legacy_credentials(){let Entry::Open(p)=parse_putty(&args(&["-ssh","-P","2222","-l","alice","-pw","a b&$","host"])).unwrap()else{panic!()};assert_eq!(p.secret.unwrap().expose(),"a b&$");let Entry::Open(w)=parse_winscp(&args(&["sftp://alice:a%3Ab%26%20word@host/a%20b","/sessionname=Work"])).unwrap()else{panic!()};assert_eq!(w.secret.unwrap().expose(),"a:b& word");assert_eq!(w.remote_path.as_deref(),Some("/a b"));for v in ["-i","-load"]{assert!(parse_putty(&args(&[v,"canary"])).is_err());}assert!(parse_winscp(&args(&["/script=canary"])).is_err());}
#[test] fn wire_is_bounded_versioned_and_secret_redacted(){let r=open(&["open","alice@host","--password","canary"]);assert!(!format!("{r:?}").contains("canary"));let bytes=encode(&r).unwrap();assert_eq!(decode(&bytes).unwrap().secret.unwrap().expose(),"canary");assert!(decode(&vec![0;MAX_FRAME+1]).is_err());assert!(decode(br#"{"version":99}"#).is_err());}
#[test] fn saved_follow_identity_survives_external_activation(){use helixlane::{settings::Settings,workspace::*};let mut s=Settings::default();let saved=s.workspace.open(ToolKind::Terminal,TargetMode::Follow);s.workspace.views[0].session_id=Some(99);let r=open(&["open","alice@host","--new-view"]);let temp=r.apply(&mut s.workspace).unwrap().view_id;let baseline=s.persistent_snapshot();for _ in 0..5 {let activate=open(&["open","alice@host","--activate"]);assert_eq!(activate.apply(&mut s.workspace).unwrap().view_id,saved);assert!(!s.workspace.views.iter().find(|v|v.id==saved).unwrap().ephemeral);assert_eq!(s.workspace.views.iter().find(|v|v.id==saved).unwrap().session_id,Some(99));assert_eq!(s.persistent_snapshot().workspace,baseline.workspace);}s.workspace.set_mode(temp,TargetMode::Fixed(1));assert!(!s.persistent_snapshot().workspace.views.iter().any(|v|v.id==temp));assert!(s.workspace.views.iter().any(|v|v.id==temp));}
#[test] fn new_window_has_no_workspace_side_effects(){let r=open(&["open","alice@host","--new-window"]);let mut w=helixlane::workspace::Workspace::default();let before=w.clone();assert!(r.apply(&mut w).is_err());assert_eq!(w,before);}
